const result=await fetch("http://127.0.0.1:4000/__review__/evidence?ref="+encodeURIComponent(dir+"/result.md"));
const liveText=await result.text(),trace=fs.readFileSync("REVIEW-TRACEABILITY.md","utf8"),walk=fs.readFileSync("verification/host-corrections-walkthrough.md","utf8");
