console.log(JSON.stringify({checks,html_sha256:manifest.html_sha256,traceability_sha256:sha(Buffer.from(trace)),walkthrough_sha256:sha(Buffer.from(walk)),current_result:visible.resultRef,buckets:visible.buckets,scope:"Final exact HTML, current result and localhost readback; no product or payment execution."},null,2));if(!Object.values(checks).every(Boolean))process.exitCode=1;

